#pragma once

#include "EqConstants.h"
#include "EqSettings.h"

#include <array>
#include <cstdint>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <vector>

namespace wce {

struct EqPreset {
    std::string name;
    BandArray bands = kFlatBands;
    int preamp = kSliderCenter;
};

// The 18 built-in presets generated by CreateEQPresets in Src/Winamp/main.cpp.
const std::array<EqPreset, 18>& builtInPresets();

// Binary header of Winamp.q1, Winamp.q2, and .eqf files (Src/Winamp/Eq.cpp):
// "Winamp EQ library file v1.1\x1A!--" (31 bytes), followed by 268-byte records
// (257-byte null-padded name + 10-byte eq_tab + 1-byte preamp).
inline constexpr std::string_view kEqfSignature = "Winamp EQ library file v1.1\x1A!--";
inline constexpr std::size_t kEqfNameFieldSize = 257;
inline constexpr std::size_t kEqfRecordSize = kEqfNameFieldSize + kBandCount + 1;

// Reads all preset entries from a .eqf or Winamp.q1 binary buffer.
std::vector<EqPreset> parseEqfFile(std::span<const std::uint8_t> bytes);

// Writes one or more preset entries in Winamp's .eqf / Winamp.q1 binary format.
// Single-preset .eqf files written by ID_SAVE_EQF use the name "Entry1".
std::vector<std::uint8_t> serializeEqfFile(std::span<const EqPreset> presets);

// Convenience helper for a single-preset .eqf file ("Entry1").
std::vector<std::uint8_t> serializeSingleEqf(const BandArray& bands, int preamp,
                                             std::string_view entryName = "Entry1");

} // namespace wce
